def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def candidatas():
    cache = Path.home() / '.bastiao_etapa3'
    ordem = []
    instalador = Path.home() / 'storage' / 'downloads' / 'BASTIAO_ETAPA3.py'
    try:
        achado = re.search(r"^SHA256 = '([0-9a-f]{64})'", instalador.read_text(errors='replace'), re.M)
        if achado:
            ordem.append(cache / ('pacote_' + achado.group(1)[:20]))
    except OSError:
        pass
    for pasta in sorted(cache.glob('pacote_*')):
        if pasta not in ordem:
            ordem.append(pasta)
    return [p for p in ordem if (p / 'instalar.py').is_file()]


def dados(item):
    raw = zlib.decompress(base64.b85decode(item['dados']))
    if sha(raw) != item['novo']:
        raise SystemExit('ERRO: este arquivo de correcao esta corrompido; baixe de novo.')
    return raw


def plano_mesclado(alvo):
    """Plano de áudio de outra versão: troca/acrescenta só os 8 sons desta correção."""
    try:
        plano = json.loads(alvo.read_text(encoding='utf-8'))
    except (OSError, ValueError):
        return None
    if not isinstance(plano, dict) or plano.get('schemaVersion') != 1 or not isinstance(plano.get('clips'), list):
        return None
    clipes = json.loads(zlib.decompress(base64.b85decode(CLIPES)).decode('utf-8'))
    chaves = [c.get('key') if isinstance(c, dict) else None for c in plano['clips']]
    for clipe in clipes:
        if clipe['key'] in chaves:
            plano['clips'][chaves.index(clipe['key'])] = clipe
        else:
            plano['clips'].append(clipe)
            chaves.append(clipe['key'])
    return (json.dumps(plano, ensure_ascii=False, indent=2) + '\n').encode('utf-8')


def gravar(alvo, raw):
    alvo.parent.mkdir(parents=True, exist_ok=True)
    temporario = alvo.with_name(alvo.name + '.novo_tmp')
    temporario.write_bytes(raw)
    temporario.replace(alvo)
    if alvo.read_bytes() != raw:
        raise SystemExit('ERRO: nao consegui gravar ' + str(alvo))


def corrigir(pasta):
    estado = {}
    for rel, item in ARQUIVOS.items():
        alvo = pasta / rel
        modo = item['modo']
        if alvo.is_symlink():
            return 'pulado (' + rel + ' e um atalho; nada foi mexido nesta pasta)'
        if not alvo.exists():
            if modo in ('criar', 'criar_teste'):
                estado[rel] = 'criar'
                continue
            if modo == 'teste':
                estado[rel] = 'pular'
                continue
            return 'pulado (falta ' + rel + ')'
        if not alvo.is_file():
            return 'pulado (' + rel + ' nao e arquivo)'
        atual = sha(alvo.read_bytes())
        if atual == item['novo']:
            estado[rel] = 'ja'
        elif atual in item['antes'] or modo in ('criar', 'criar_teste'):
            estado[rel] = 'trocar'
        elif modo == 'teste':
            estado[rel] = 'pular'
        elif modo == 'plano' and plano_mesclado(alvo) is not None:
            estado[rel] = 'mesclar'
        else:
            return 'pulado (versao diferente de ' + rel + '; nada foi mexido nesta pasta)'
    trocados = 0
    for rel, item in ARQUIVOS.items():
        acao = estado[rel]
        if acao in ('ja', 'pular'):
            continue
        alvo = pasta / rel
        if acao in ('trocar', 'mesclar'):
            copia = alvo.with_name(alvo.name + '.antes_correcao9')
            if not copia.exists():
                shutil.copy2(alvo, copia)
        if acao == 'mesclar':
            raw = plano_mesclado(alvo)
            json.loads(raw.decode('utf-8'))
        else:
            raw = dados(item)
        gravar(alvo, raw)
        trocados += 1
    return 'corrigido (' + str(trocados) + ' arquivos)' if trocados else 'ja estava corrigido'


pastas = candidatas()
if not pastas:
    raise SystemExit('ERRO: nao achei a pasta do pacote em ~/.bastiao_etapa3. Rode antes: '
                     'python ~/storage/downloads/BASTIAO_ETAPA3.py status')
alguma = False
for pasta in pastas:
    resultado = corrigir(pasta)
    alguma = alguma or resultado.startswith(('corrigido', 'ja estava'))
    print('Pacote', pasta.name + ':', resultado)
if not alguma:
    raise SystemExit('ERRO: nenhuma pasta do pacote bateu com a versao esperada. Nada foi mexido.')
print('PRONTO. Agora rode:  python ~/storage/downloads/BASTIAO_ETAPA3.py preparar-audio')
print('(se pedir a chave do ElevenLabs, so aperte Enter; depois: assets, testar-nuvem e publicar)')
